// js/services/apiClient.js
/**
 * Shared HTTP utilities for Kamsan service modules.
 * This module deliberately knows nothing about page elements or features.
 */
class ApiError extends Error {
  constructor(message, { status, statusText, body } = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.statusText = statusText;
    this.body = body;
  }
}

async function request(url, options = {}) {
  const response = await fetch(url, options);
  const contentType = response.headers.get('content-type') || '';
  const body = contentType.includes('application/json')
    ? await response.json()
    : await response.text();

  if (!response.ok) {
    throw new ApiError(`Request failed with status ${response.status}.`, {
      status: response.status,
      statusText: response.statusText,
      body,
    });
  }

  return body;
}

// js/services/reviewApi.js

const REVIEWS_API_URL = 'https://jsonplaceholder.typicode.com/posts';

function reviewUrl(reviewId) {
  return `${REVIEWS_API_URL}/${encodeURIComponent(reviewId)}`;
}

function jsonOptions(method, review) {
  return {
    method,
    headers: { 'Content-Type': 'application/json; charset=UTF-8' },
    body: JSON.stringify(review),
  };
}

/** Returns demo reviews from JSONPlaceholder. */
async function getReviews({ limit = 10 } = {}) {
  const parameters = new URLSearchParams({ _limit: String(limit) });
  return request(`${REVIEWS_API_URL}?${parameters}`);
}

/** Creates a demo review. JSONPlaceholder echoes it but does not persist it. */
function createReview(review) {
  return request(REVIEWS_API_URL, jsonOptions('POST', review));
}

/** Updates a demo review. JSONPlaceholder does not persist this change. */
function updateReview(reviewId, review) {
  return request(reviewUrl(reviewId), jsonOptions('PUT', review));
}

/** Deletes a demo review. JSONPlaceholder does not persist this change. */
async function deleteReview(reviewId) {
  await request(reviewUrl(reviewId), { method: 'DELETE' });
  return { id: reviewId, deleted: true };
}

// js/utils/dom.js
/** Returns the first element that matches a selector within an optional scope. */
function select(selector, scope = document) {
  return scope.querySelector(selector);
}

/** Returns all matching elements as an array, making array methods safe to use. */
function selectAll(selector, scope = document) {
  return Array.from(scope.querySelectorAll(selector));
}

/** Creates an element with common content, data, and accessibility properties. */
function createElement(tagName, options = {}) {
  const { attributes = {}, className, dataset = {}, text } = options;
  const element = document.createElement(tagName);

  if (className) {
    element.className = className;
  }

  if (text !== undefined) {
    element.textContent = text;
  }

  Object.entries(attributes).forEach(([name, value]) => {
    element.setAttribute(name, value);
  });

  Object.entries(dataset).forEach(([name, value]) => {
    element.dataset[name] = value;
  });

  return element;
}

/** Replaces all children of an element. */
function clearElement(element) {
  element.replaceChildren();
}

/** Updates text content without treating text as HTML. */
function setText(element, text) {
  element.textContent = text;
}

/** Renders a short loading message in a live region. */
function renderLoading(element, message = 'Loading…') {
  element.replaceChildren(createElement('p', { className: 'loading-message', text: message }));
  element.setAttribute('aria-busy', 'true');
}

/** Renders an accessible error message without injecting HTML. */
function renderError(element, message = 'Something went wrong. Please try again.') {
  element.replaceChildren(
    createElement('p', {
      className: 'error-message',
      attributes: { role: 'alert' },
      text: message,
    })
  );
  element.removeAttribute('aria-busy');
}

/** Shows a temporary, accessible notification. */
function toast(message, { duration = 4000, root = document } = {}) {
  let region = select('[data-toast-region]', root);

  if (!region) {
    region = createElement('div', {
      className: 'toast-region',
      dataset: { toastRegion: '' },
      attributes: { 'aria-live': 'polite', 'aria-atomic': 'true' },
    });
    (root.body || root).append(region);
  }

  const notification = createElement('p', { className: 'toast', text: message });
  region.append(notification);

  if (duration > 0) {
    window.setTimeout(() => notification.remove(), duration);
  }

  return notification;
}

